[et_pb_section fb_built="1" module_class="g2" module_id="g2" background_enable_color="off" custom_padding="0px||0px||true|false" admin_label="Gitta - the record" _builder_version="4.27.4"][et_pb_row module_class="g2-stage-row" width="100%" max_width="none" custom_padding="0px||0px||true|false" admin_label="The record - prose left, deck right" _builder_version="4.27.4"][et_pb_column type="2_3" _builder_version="4.27.4"][et_pb_text module_class="tod-reveal" admin_label="Hero copy - click and write over it" _builder_version="4.27.4"]<header class="hero-copy"><p class="eyebrow">About me</p><h1>Gitta</h1><p class="tagline">DJ from Portugal. Home is wherever the system is.</p><p class="intro">Twenty years on the move, always close to water and music. Whatever is left of that sits in the record crates now.</p></header>[/et_pb_text][et_pb_text module_class="tod-reveal" admin_label="Side A heading" _builder_version="4.27.4"]<div class="side-head-wrap"><div class="side-head"><h2>Side A</h2><span class="note">How I got here</span></div></div>[/et_pb_text][et_pb_text module_class="tod-reveal g2-chapter" admin_label="Track 0 - First record (keep the g2-chapter class)" _builder_version="4.27.4"]<article class="track" data-track="0"><span class="no">01</span><h3>First record</h3><p class="where">Portugal</p><p class="body">Raised with a radio that was never quite off. Music came before language, and it stayed when everything else changed.</p></article>[/et_pb_text][et_pb_text module_class="tod-reveal g2-chapter" admin_label="Track 1 - North Sea instead of Atlantic (keep the g2-chapter class)" _builder_version="4.27.4"]<article class="track" data-track="1"><span class="no">02</span><h3>North Sea instead of Atlantic</h3><p class="where">Skegness, England</p><p class="body">Cold water, grey piers, another language. The years where leaving turned into living somewhere.</p></article>[/et_pb_text][et_pb_text module_class="tod-reveal g2-chapter" admin_label="Track 2 - The long left (keep the g2-chapter class)" _builder_version="4.27.4"]<article class="track" data-track="2"><span class="no">03</span><h3>The long left</h3><p class="where">Manu Bay, Raglan</p><p class="body">New Zealand, west coast, a wave that does not stop. Most of the photos in the archive below come from that stretch.</p></article>[/et_pb_text][et_pb_text module_class="tod-reveal" admin_label="Side B heading" _builder_version="4.27.4"]<div class="side-head-wrap"><div class="side-head"><h2>Side B</h2><span class="note">Now</span></div></div>[/et_pb_text][et_pb_text module_class="tod-reveal g2-chapter" admin_label="Track 3 - Black sand (keep the g2-chapter class)" _builder_version="4.27.4"]<article class="track" data-track="3"><span class="no">04</span><h3>Black sand</h3><p class="where">Piha</p><p class="body">Yoga on the beach, up early, down late. The part that still explains why the sets open the way they open.</p></article>[/et_pb_text][et_pb_text module_class="tod-reveal g2-chapter" admin_label="Track 4 - Titis on Decks (keep the g2-chapter class)" _builder_version="4.27.4"]<article class="track" data-track="4"><span class="no">05</span><h3>Titis on Decks</h3><p class="where">Today</p><p class="body">Housey, warm, with enough Portugal in it that nobody can file it properly. Preferably late, preferably long, preferably for people who stay.</p></article>[/et_pb_text][/et_pb_column][et_pb_column type="1_3" _builder_version="4.27.4"][et_pb_code admin_label="Turntable + tonearm - leave as is (geometry, not content)" _builder_version="4.27.4"]<style>
@import url("https://fonts.googleapis.com/css2?family=Unbounded:wght@400;600;800&family=Work+Sans:ital,wght@0,300;0,400;0,500;1,400&family=Space+Mono:wght@400;700&display=swap");

/* ============================================================
   TOKENS
   base = the dark "home" theme of the site
   [data-theme="pink"] = Gitta's theme, hot pink into violet
   ============================================================ */
.g2{
  --ink:        #0b0710;
  --ink-2:      #150c1e;
  --edge:       rgba(255,255,255,.09);
  --paper:      #f7efff;
  --muted:      rgba(232,214,255,.60);
  --accent:     #c9a9ff;
  --accent-2:   #8f3bff;
  --glow:       rgba(255,46,139,.35);
  --font-display:'Unbounded', system-ui, sans-serif;
  --font-body:  'Work Sans', system-ui, sans-serif;
  --font-mono:  'Space Mono', ui-monospace, monospace;
  --rail: clamp(1.15rem, 5vw, 4.5rem);
}
.g2{
  --ink:      #0a0410;
  --ink-2:    #170a22;
  --accent:   #ff2e8b;
  --accent-2: #8f3bff;
  --glow:     rgba(255,46,139,.38);
}

.g2, .g2 *, .g2 *::before, .g2 *::after{ box-sizing:border-box; }
.g2{ scroll-behavior:smooth; }
.g2{
  margin:0;
  background:var(--ink);
  color:var(--paper);
  font-family:var(--font-body);
  font-weight:300;
  font-size:clamp(1rem,.96rem + .25vw,1.09rem);
  line-height:1.62;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
.g2::before{ /* one soft light source, top right, nothing more */
  content:"";
  position:fixed; inset:0; pointer-events:none; z-index:0;
  background:
    radial-gradient(58vw 46vw at 88% -6%, rgba(143,59,255,.22), transparent 62%),
    radial-gradient(46vw 40vw at 6% 108%, rgba(255,46,139,.14), transparent 64%);
}
.g2 a{ color:inherit; }
.g2 :focus-visible{ outline:2px solid var(--accent); outline-offset:3px; border-radius:2px; }

.g2 .wrap{ position:relative; z-index:1; max-width:1180px; margin-inline:auto; padding-inline:var(--rail); }

.g2 .eyebrow{
  font-family:var(--font-mono); font-size:.72rem; letter-spacing:.22em;
  text-transform:uppercase; color:var(--accent); margin:0;
}

/* ---------- top bar ---------- */
.g2 .topbar{
  position:relative; z-index:3;
  display:flex; align-items:center; justify-content:space-between; gap:1rem;
  padding-block:1.15rem 0;
}
.g2 .back{
  font-family:var(--font-mono); font-size:.74rem; letter-spacing:.16em;
  text-transform:uppercase; text-decoration:none; color:var(--muted);
  display:inline-flex; align-items:center; gap:.55rem; transition:color .2s;
}
.g2 .back:hover{ color:var(--paper); }
.g2 .back span{ color:var(--accent); }
.g2 .langs{ display:flex; gap:.15rem; }
.g2 .langs button{
  font-family:var(--font-mono); font-size:.72rem; letter-spacing:.1em;
  background:none; border:0; color:var(--muted); cursor:pointer;
  padding:.4rem .55rem; border-radius:99px; transition:color .2s, background .2s;
}
.g2 .langs button:hover{ color:var(--paper); }
.g2 .langs button[aria-pressed="true"]{ color:var(--ink); background:var(--accent); }

/* ---------- stage: copy left, deck sticky right ---------- */
.g2 .stage{
  display:grid; grid-template-columns:1fr;
  grid-template-areas:"hero" "deck" "list";
  row-gap:clamp(2rem,5vw,3rem);
  padding-block:clamp(2.2rem,6vw,4.5rem) 0;
}
@media (min-width:900px){
  .g2 .stage{
    grid-template-columns:minmax(0,1fr) minmax(300px,.76fr);
    grid-template-areas:"hero deck" "list deck";
    column-gap:clamp(2rem,5vw,4.5rem);
    align-items:start; row-gap:0;
  }
  .g2 .stage-deck{ align-self:stretch; }
  .g2 .deck-inner{ position:sticky; top:12vh; }
}
.g2 .hero-copy{ grid-area:hero; }
.g2 .stage-deck{ grid-area:deck; }
.g2 .list{ grid-area:list; }

.g2 .hero-copy h1{
  font-family:var(--font-display); font-weight:800;
  font-size:clamp(3.6rem,11vw,6.6rem); line-height:.86;
  letter-spacing:-.03em; margin:.7rem 0 0;
  background:linear-gradient(102deg,var(--paper) 18%,var(--accent) 62%,var(--accent-2) 96%);
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.g2 .hero-copy .tagline{
  font-size:clamp(1.12rem,1rem + .7vw,1.42rem); font-weight:300;
  margin:1.15rem 0 0; max-width:32ch; color:var(--paper);
}
.g2 .hero-copy .intro{ margin:1.1rem 0 0; max-width:42ch; color:var(--muted); }

.g2 .transport{ display:flex; align-items:center; gap:1rem; margin-top:2rem; flex-wrap:wrap; }
.g2 .play{
  display:inline-flex; align-items:center; gap:.7rem;
  font-family:var(--font-mono); font-size:.76rem; letter-spacing:.16em; text-transform:uppercase;
  color:var(--paper); background:rgba(255,255,255,.05);
  border:1px solid var(--edge); border-radius:99px; padding:.7rem 1.25rem .7rem .95rem;
  cursor:pointer; transition:border-color .2s, background .2s, transform .12s;
}
.g2 .play:hover{ border-color:var(--accent); background:rgba(255,46,139,.1); }
.g2 .play:active{ transform:translateY(1px); }
.g2 .play .icon{ width:9px; height:11px; flex:none; background:var(--accent); clip-path:polygon(0 0,100% 50%,0 100%); }
.g2.playing .play .icon{
  clip-path:none;
  background:linear-gradient(90deg,var(--accent) 0 34%,transparent 34% 66%,var(--accent) 66% 100%);
}
.g2 .rpm{ font-family:var(--font-mono); font-size:.7rem; letter-spacing:.14em; color:var(--muted); }

/* ---------- turntable ---------- */
.g2 .deck{ position:relative; width:min(430px,84vw); margin-inline:auto; aspect-ratio:1; }
.g2 .platter{
  position:absolute; left:0; top:7%; width:86%; aspect-ratio:1; border-radius:50%;
  background:
    repeating-radial-gradient(circle at 50% 50%, rgba(255,255,255,.05) 0 1px, transparent 1px 4px),
    radial-gradient(circle at 50% 50%, #241132 0 32%, #120818 33% 100%);
  box-shadow:0 34px 70px rgba(0,0,0,.6), 0 0 0 1px var(--edge), inset 0 0 70px rgba(255,46,139,.08);
}
.g2 .platter::after{ /* static sheen, does not spin */
  content:""; position:absolute; inset:0; border-radius:50%;
  background:conic-gradient(from 210deg, transparent 0 14%, rgba(255,255,255,.09) 22%, transparent 32% 66%, rgba(255,46,139,.12) 76%, transparent 86%);
  mix-blend-mode:screen; pointer-events:none;
}
.g2 .label{
  position:absolute; left:50%; top:50%; width:31%; aspect-ratio:1;
  transform:translate(-50%,-50%); border-radius:50%; overflow:hidden;
  background:linear-gradient(135deg,var(--accent),var(--accent-2));
  display:grid; place-items:center;
  box-shadow:0 0 30px var(--glow);
  animation:spin 3.6s linear infinite; animation-play-state:paused;
}
.g2.playing .label{ animation-play-state:running; }
.g2 .label img{ width:100%; height:100%; object-fit:cover; display:block; }
.g2 .label .initial{
  font-family:var(--font-display); font-weight:800; font-size:clamp(1.6rem,4.6vw,2.4rem);
  color:var(--ink); letter-spacing:-.02em;
}
.g2 .label::after{
  content:""; position:absolute; left:50%; top:50%; width:9%; aspect-ratio:1;
  transform:translate(-50%,-50%); border-radius:50%;
  background:var(--ink); box-shadow:0 0 0 2px rgba(0,0,0,.5);
}
@keyframes spin{ to{ transform:translate(-50%,-50%) rotate(360deg); } }

.g2 .arm{ position:absolute; inset:0; width:100%; height:100%; overflow:visible; }
.g2 .arm .tube{ stroke:#d3c3de; stroke-width:1.1; stroke-linecap:round; }
.g2 .arm .shell{ fill:#e6d8f2; }
.g2 .arm .stylus{ fill:var(--accent); }
.g2 .arm .halo{ fill:var(--accent); opacity:0; transition:opacity .4s; }
.g2.playing .arm .halo{ opacity:.3; }
.g2 .arm .pivot{ fill:#3b2450; stroke:rgba(255,255,255,.3); stroke-width:.5; }
.g2 .arm .base{ fill:#180d24; stroke:var(--edge); stroke-width:.5; }
.g2 .arm .weight{ fill:#4a2e63; stroke:rgba(255,255,255,.18); stroke-width:.5; }
.g2 .arm .rest{ fill:#180d24; stroke:var(--edge); stroke-width:.5; }
.g2 #armGroup{ transition:transform .55s cubic-bezier(.22,.9,.28,1); }
.g2 .ring{ fill:none; stroke:rgba(255,255,255,.14); stroke-width:.4; transition:stroke .35s, stroke-width .35s, opacity .35s; }
.g2 .ring.on{ stroke:rgba(255,46,139,.72); stroke-width:.7; filter:drop-shadow(0 0 1.4px var(--glow)); }

/* ---------- tracklist ---------- */
.g2 .side{ padding-block:clamp(1.6rem,4vw,2.6rem) 0; }
.g2 .side-head{
  display:flex; align-items:baseline; gap:1rem;
  border-top:1px solid var(--edge); padding-top:1.1rem; margin-bottom:.6rem;
}
.g2 .side-head h2{
  font-family:var(--font-display); font-weight:600; font-size:1rem;
  letter-spacing:.02em; margin:0;
}
.g2 .side-head .note{ font-family:var(--font-mono); font-size:.72rem; color:var(--muted); letter-spacing:.1em; }

.g2 .track{
  display:grid; gap:.35rem 1.6rem; grid-template-columns:auto 1fr;
  padding:1.5rem 0; border-bottom:1px solid rgba(255,255,255,.055);
  opacity:.5; transition:opacity .5s ease;
}
.g2 .track.live{ opacity:1; }
.g2 .track .no{
  font-family:var(--font-mono); font-size:.78rem; letter-spacing:.12em;
  color:var(--muted); padding-top:.42rem; transition:color .4s;
}
.g2 .track.live .no{ color:var(--accent); }
.g2 .track h3{
  font-family:var(--font-display); font-weight:600;
  font-size:clamp(1.5rem,1.1rem + 1.7vw,2.35rem); line-height:1.14;
  letter-spacing:-.02em; margin:0;
}
.g2 .track .where{
  grid-column:2; font-family:var(--font-mono); font-size:.72rem;
  letter-spacing:.16em; text-transform:uppercase; color:var(--accent);
  margin:.5rem 0 0;
}
.g2 .track p.body{ grid-column:2; margin:.55rem 0 0; max-width:56ch; color:var(--muted); }
.g2 .track.live p.body{ color:rgba(247,239,255,.86); }

/* ---------- archive strip ---------- */
.g2 .archive{ padding-block:clamp(3.5rem,9vw,6rem) 0; }
.g2 .archive-head{ display:flex; flex-wrap:wrap; align-items:baseline; gap:.6rem 1.4rem; }
.g2 .archive-head h2{
  font-family:var(--font-display); font-weight:600; letter-spacing:-.01em;
  font-size:clamp(1.5rem,1.2rem + 1vw,2rem); margin:.5rem 0 0;
}
.g2 .archive-head p{ margin:0; color:var(--muted); font-size:.95rem; max-width:46ch; }
.g2 .strip{
  display:flex; gap:.9rem; margin-top:1.8rem;
  overflow-x:auto; scroll-snap-type:x mandatory;
  padding-bottom:1rem; padding-inline:var(--rail);
  margin-inline:calc(var(--rail) * -1);
  scrollbar-width:thin; scrollbar-color:var(--accent-2) transparent;
}
.g2 .tile{
  flex:none; width:clamp(150px,38vw,236px); aspect-ratio:4/5;
  scroll-snap-align:start; position:relative; border-radius:3px; overflow:hidden;
  border:1px solid var(--edge);
  background:
    linear-gradient(160deg, rgba(255,46,139,.30), rgba(143,59,255,.20) 58%, rgba(10,4,16,.9)),
    repeating-linear-gradient(115deg, rgba(255,255,255,.05) 0 2px, transparent 2px 9px);
}
.g2 .tile img{ position:absolute; inset:0; width:100%; height:100%; object-fit:cover; }
.g2 .tile figcaption{
  position:absolute; left:0; right:0; bottom:0; padding:.65rem .75rem;
  font-family:var(--font-mono); font-size:.68rem; letter-spacing:.1em;
  text-transform:uppercase; color:var(--paper);
  background:linear-gradient(transparent,rgba(10,4,16,.86));
}
.g2 .tile figcaption b{ display:block; font-weight:400; color:var(--muted); letter-spacing:.06em; }

/* ---------- closing ---------- */
.g2 .cta{
  margin-top:clamp(4rem,10vw,7rem); padding:clamp(2rem,5vw,3.4rem);
  border:1px solid var(--edge); border-radius:4px;
  background:linear-gradient(140deg, rgba(255,46,139,.12), rgba(143,59,255,.08) 60%, transparent);
}
.g2 .cta h2{
  font-family:var(--font-display); font-weight:800; letter-spacing:-.02em;
  font-size:clamp(2rem,1.4rem + 2.4vw,3.2rem); margin:.6rem 0 0;
}
.g2 .cta p{ margin:.8rem 0 0; color:var(--muted); max-width:44ch; }
.g2 .cta a.button{
  display:inline-block; margin-top:1.6rem; text-decoration:none;
  font-family:var(--font-mono); font-size:.78rem; letter-spacing:.16em; text-transform:uppercase;
  color:var(--ink); background:var(--accent); padding:.85rem 1.5rem; border-radius:99px;
  transition:transform .15s, box-shadow .25s;
}
.g2 .cta a.button:hover{ transform:translateY(-2px); box-shadow:0 10px 30px var(--glow); }

.g2 footer{
  margin-top:clamp(3rem,7vw,5rem); padding-block:1.6rem 3rem;
  border-top:1px solid var(--edge);
  font-family:var(--font-mono); font-size:.7rem; letter-spacing:.12em;
  text-transform:uppercase; color:var(--muted);
  display:flex; flex-wrap:wrap; gap:.6rem 1.4rem; justify-content:space-between;
}

@media (max-width:899px){ .g2 .track{ opacity:.78; } }

@media (prefers-reduced-motion:reduce){
  .g2{ scroll-behavior:auto; }
  .g2 .label{ animation:none !important; }
  .g2 #armGroup{ transition:none; }
  .g2 .track{ opacity:1; }
}


/* ---------- transform 6: the stage, rebuilt on Divi's columns ---------- */
.g2 .stage{ display:block; }
.g2 .hero-copy, .g2 .stage-deck{ align-self:auto; }

/* Divi stacks its own columns at 980px; the source grid switched at 900.
   Those 80px were a band where our CSS thought "two columns" and Divi had
   already stacked them. The split now uses Divi's breakpoint, and the
   stacking below it is stated here rather than borrowed. */
@media(max-width:980px){
  .g2 .g2-stage-row > .et_pb_column{
    float:none !important;
    width:100% !important;
    margin:0 0 clamp(2rem,6vw,3rem) !important;
  }
}

@media(min-width:981px){
  .g2 .g2-stage-row{
    display:flex !important;
    align-items:stretch !important;
    gap:clamp(2rem,5vw,4.5rem);
  }
  .g2 .g2-stage-row > .et_pb_column{
    float:none !important;
    width:auto !important;
    margin:0 !important;
  }
  .g2 .g2-stage-row > .et_pb_column_2_3{ flex:1 1 0; min-width:0; }
  .g2 .g2-stage-row > .et_pb_column_1_3{ flex:0 0 clamp(300px,30%,420px); }
  /* Sticky needs every ancestor between the column and .deck-inner to
     carry height, or the needle has nowhere to travel. The column itself
     is deliberately NOT in this list: an explicit height on a flex item
     beats align-items:stretch, and the column then collapses to its own
     content - measured 599px against the prose column's 1619px, which is
     exactly no travel at all. Let flex stretch it, size the rest. */
  .g2 .g2-stage-row .et_pb_code,
  .g2 .g2-stage-row .et_pb_code_inner,
  .g2 .g2-stage-row .stage,
  .g2 .g2-stage-row .stage-deck{ height:100%; }
}

/* ---------- transform 8: .wrap and .side lost their elements ---------- */
.g2 .et_pb_row{
  max-width:1180px !important;
  margin-inline:auto !important;
  padding-inline:var(--rail);
}
.g2 .side-head-wrap{ padding-block:clamp(1.6rem,4vw,2.6rem) 0; }
